#[cfg(feature = "binary-format")]
crate::archive_as_spelling!(ObjectType);

impl Default for ObjectType {
    fn default() -> Self {
        Self::Spelled(Box::default())
    }
}

impl From<String> for ObjectType {
    fn from(text: String) -> Self {
        match Self::value_of(&text) {
            Some(member) if crate::spells(&member, &text) => Self::Member(member),
            Some(_) | None => Self::Spelled(text.into_boxed_str()),
        }
    }
}

impl From<ObjectTypeMember> for ObjectType {
    fn from(member: ObjectTypeMember) -> Self {
        Self::Member(member)
    }
}

impl Spelling for ObjectType {
    fn spelling(&self, _class: ConformanceClass) -> Cow<'_, str> {
        match self {
            Self::Member(member) => Cow::Borrowed(member.as_str()),
            Self::Spelled(text) => Cow::Borrowed(text),
        }
    }
}

impl fmt::Display for ObjectTypeMember {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl ObjectTypeMember {
    const MEMBERS: &crate::Members<Self> = &[
        (Self::Button, "Button", None),
        (Self::Checkbox, "Checkbox", None),
        (Self::Dialog, "Dialog", None),
        (Self::Drop, "Drop", None),
        (Self::Edit, "Edit", None),
        (Self::GBox, "GBox", None),
        (Self::Label, "Label", None),
        (Self::LineA, "LineA", None),
        (Self::List, "List", None),
        (Self::Movie, "Movie", None),
        (Self::Note, "Note", None),
        (Self::Pict, "Pict", None),
        (Self::Radio, "Radio", None),
        (Self::RectA, "RectA", None),
        (Self::Scroll, "Scroll", None),
        (Self::Spin, "Spin", None),
        (Self::Shape, "Shape", None),
        (Self::Group, "Group", None),
        (Self::Rect, "Rect", None),
    ];

    /// The text the member stands for.
    #[must_use = "this only returns the text of the member"]
    pub fn as_str(self) -> &'static str {
        crate::member_text(Self::MEMBERS, self)
    }

    /// The Office version that brought the member, from the data of the Open XML SDK, version 3.5.1; `None` for
    /// ECMA-376's own.
    #[must_use = "this only returns the Office version of the member"]
    pub fn introduced(self) -> Option<OfficeVersion> {
        crate::member_version(Self::MEMBERS, self)
    }
}

impl ObjectType {
    /// The value `text` spells.
    ///
    /// # Errors
    ///
    /// `ValueError` when `text` is no value of `ST_ObjectType`.
    pub fn parse(text: &str) -> Result<ObjectTypeMember, ValueError> {
        Self::value_of(text).ok_or_else(|| crate::invalid(text, "ST_ObjectType"))
    }

    /// The member the value keeps, or the one its spelling spells.
    ///
    /// # Errors
    ///
    /// `ValueError` when a kept spelling is no value of `ST_ObjectType`.
    pub fn value(&self) -> Result<ObjectTypeMember, ValueError> {
        match self {
            Self::Member(member) => Ok(*member),
            Self::Spelled(text) => Self::parse(text),
        }
    }

    /// The value `text` spells; `None` when it spells none.
    #[must_use = "this only returns the value"]
    pub fn value_of(text: &str) -> Option<ObjectTypeMember> {
        crate::member(ObjectTypeMember::MEMBERS, text)
    }
}

